package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer_deserialize_TriageGen0Test {

    private StringArrayDeserializer deserializer;
    private JsonParser jp;
    private DeserializationContext ctxt;
    private ObjectBuffer buffer;

    @Before
    public void setUp() throws Exception {
        deserializer = new StringArrayDeserializer();
        jp = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        buffer = mock(ObjectBuffer.class);

        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);
        // Mock buffer behavior
        when(buffer.resetAndStart()).thenReturn(new Object[2]);
        // Mock completeAndClearBuffer to return a String array based on provided length
        when(buffer.completeAndClearBuffer(any(Object[].class), anyInt(), eq(String.class)))
                .thenAnswer(invocation -> {
                    Object[] chunk = invocation.getArgument(0);
                    int length = invocation.getArgument(1);
                    String[] result = new String[length];
                    for (int i = 0; i < length; i++) {
                        result[i] = (String) chunk[i];
                    }
                    return result;
                });
    }

    @Test
    public void testDeserialize_NonArrayToken() throws IOException {
        // Use a spy to access handleNonArray if it's protected/package-private
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        when(jp.isExpectedStartArrayToken()).thenReturn(false);
        when(spyDeserializer.handleNonArray(jp, ctxt)).thenReturn(new String[]{"notAnArray"});

        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"notAnArray"}, result);
        verify(spyDeserializer).handleNonArray(jp, ctxt);
    }

    @Test
    public void testDeserialize_CustomDeserializerPresent() throws IOException {
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        // Set _elementDeserializer via reflection to trigger _deserializeCustom
        Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(spyDeserializer, mock(com.fasterxml.jackson.databind.JsonDeserializer.class));

        String[] expected = new String[]{"custom"};
        doReturn(expected).when(spyDeserializer)._deserializeCustom(jp, ctxt);

        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertArrayEquals(expected, result);
        verify(spyDeserializer)._deserializeCustom(jp, ctxt);
    }

    @Test
    public void testDeserialize_StandardArrayWithMixedTokens() throws IOException {
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        // Sequence: START_ARRAY, STRING, NULL, NUMBER (triggering _parseString), END_ARRAY
        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.VALUE_NULL)
                .thenReturn(JsonToken.VALUE_NUMBER_INT)
                .thenReturn(JsonToken.END_ARRAY);

        when(jp.getText()).thenReturn("hello");

        // Mock _parseString (it's protected, so we use a spy)
        StringArrayDeserializer spyDeserializer = spy(deserializer);
        doReturn("123").when(spyDeserializer)._parseString(jp, ctxt);

        // Re-inject the spy to handle the _parseString call
        // Since we can't easily replace the instance inside the method call if we don't use a spy,
        // we assume the method is being tested via the spy.
        // However, the method being tested is the one in the class.
        // To test _parseString branch, we must use the spy.

        String[] result = spyDeserializer.deserialize(jp, ctxt);

        // Expected: ["hello", null, "123"]
        // Note: chunk size is 2 in setUp, so it will trigger appendCompletedChunk
        String[] expected = {"hello", null, "123"};
        assertArrayEquals(expected, result);

        verify(buffer).appendCompletedChunk(any(Object[].class));
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserialize_EmptyArray() throws IOException {
        when(jp.isExpectedStartArrayToken()).thenReturn(true);
        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertEquals(0, result.length);
        verify(buffer).completeAndClearBuffer(any(Object[].class), eq(0), eq(String.class));
    }

    @Test
    public void testDeserialize_BufferExpansion() throws IOException {
        when(jp.isExpectedStartArrayToken()).thenReturn(true);

        // Initial chunk size is 2. We provide 3 elements to force expansion.
        when(jp.nextToken())
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(jp.getText()).thenReturn("a", "b", "c");

        // Mock buffer expansion
        Object[] secondChunk = new Object[2];
        when(buffer.appendCompletedChunk(any(Object[].class))).thenReturn(secondChunk);

        StringArrayDeserializer spyDeserializer = spy(deserializer);
        String[] result = spyDeserializer.deserialize(jp, ctxt);

        assertArrayEquals(new String[]{"a", "b", "c"}, result);
        verify(buffer).appendCompletedChunk(any(Object[].class));
    }
}
